import{_ as i,a0 as p,w as s,s as l,ao as d,I as a,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"英伟达开始着手为未来的开放和并行编程建立基础 | LCTT x X-CMD","titleTemplate":false,"description":"英伟达开始着手为未来的开放和并行编程建立基础 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英伟达开始着手为未来的开放和并行编程建立基础 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英伟达开始着手为未来的开放和并行编程建立基础 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220503 Nvidia Begins To Set The Foundation For Future Open And Parallel Coding","title":"英伟达开始着手为未来的开放和并行编程建立基础","tag":"202205","desc":""},"relativePath":"202205/20220503 Nvidia Begins To Set The Foundation For Future Open And Parallel Coding.md","filePath":"[post].md"}'),u={name:"202205/20220503 Nvidia Begins To Set The Foundation For Future Open And Parallel Coding.md"};function C(f,t,T,m,g,x){const o=p("Link");return s(),l("div",null,[t[15]||(t[15]=d('<h1 id="英伟达开始着手为未来的开放和并行编程建立基础" tabindex="-1">英伟达开始着手为未来的开放和并行编程建立基础 <a class="header-anchor" href="#英伟达开始着手为未来的开放和并行编程建立基础" aria-label="Permalink to “英伟达开始着手为未来的开放和并行编程建立基础”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/09/080227sdxqcd3rxooc3cq3.jpg" alt=""></p><p>随着图形处理器在计算机里变得越来越常见，英伟达正在扩大与标准和开源社区的合作，以便于包括先前仅限于该公司开发工具的下游技术。虽然人们在 C++ 和 Fortran 等语言上投入了大量精力，但这些语言被认为在高度并行的计算机上执行代码落后于原生实现的编程语言。</p><p>英伟达结合了开放和专有库的 CUDA 并行编程框架影响了许多正在开放和主流化的技术。在 2007 年，CUDA 作为一个为程序员开发基于 GPU 的系统的一系列编程工具和框架而推出。然而，随着 GPU 利用率在更多应用程序和领域中的增长，CUDA 理念发生了转变。</p><p>英伟达因其在 GPU 上的主导地位而广为人知，但 CUDA 是这家以 1 万亿市值为目标的软件和服务供应商重塑品牌的核心。英伟达的长期目标是成为一个全栈提供商，专注于自动驾驶、量子计算、医疗保健、机器人、网络安全和量子计算等特定领域。</p><p>英伟达已经在特定领域创建了专用的 CUDA 库，以及企业可以使用的硬件和服务。其 CEO 黄仁勋在最近的 GPU 技术大会上宣布的 “AI 工厂” 概念，最能体现全栈战略。客户可以将应用程序放入英伟达的大型数据中心，从而获得针对特定行业或应用程序需求量身定制的定制 AI 模型。</p><p>英伟达可以通过两种方式从 AI 工厂原则中受益：利用 GPU 容量或利用特定领域的 CUDA 库。在英伟达 GPU 上，程序员可以使用 OpenCL 等开源并行编程框架。另一方面，CUDA 将为那些愿意投资的人提供额外的最后一英里增长，因为其已调整为与英伟达的 GPU 密切运作。</p><p>虽然并行编程在高性能计算中很常见常见，但英伟达的目标是让其成为主流计算的标准。该公司正在协助实现一流工具的标准化，无论品牌、加速器类型或并行编程框架是什么，都可以编写可跨硬件平台移植的并行代码。</p><p>一方面，英伟达是 C++ 小组的成员，该小组正在为跨硬件同时执行可移植代码奠定基础。上下文可以是主要执行 IO 的 CPU 线程，也可以是执行高要求计算的 CPU 或 GPU 线程。英伟达特别致力于为 C++ 程序员提供异步和并行的标准语言和基础设施。</p><p>第一项工作侧重于内存模型，该模型已合并到 C++ 11 中，但当并行性和并发性变得更加普遍时，必须对其进行更新。C++ 11 的内存模型强调跨多核 CPU 的并发执行，但它缺乏并行编程钩子。C++ 17 标准为更高级别的并行特性奠定了基础，但真正的可移植性必须等待未来的标准。C++ 20 是当前标准，而 C++ 23 即将推出。</p><hr>',11)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"https://www.opensourceforu.com/2022/05/nvidia-begins-to-set-the-foundation-for-future-open-and-parallel-coding/"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/05/nvidia-begins-to-set-the-foundation-for-future-open-and-parallel-coding/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=e("作者：",-1)),n(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:r(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),n(o,{href:"https://github.com/zxcv545"},{default:r(()=>[...t[4]||(t[4]=[e("zxcv545",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const v=i(u,[["render",C]]);export{U as __pageData,v as default};
